      (let* ([angle (* jd (add1 i) (/ (* 2 pi) 365.25))]
             [orbit-x (* (sin angle) (list-ref (reverse (hash-ref zo 'astro-offset)) i))]
             [orbit-y (* (cos angle) (list-ref (reverse (hash-ref zo 'astro-offset)) i))])
        (set! result (cons (* param 1.0 (+ orbit-x 0.05)) result))
        (set! result (cons (* orbit-y 0.05) result))))
    (reverse result)))

