  (let* ([orig (list-ref params dim)]
         [plus-params (list-set params dim (+ orig (* (caar (hash-ref zo 'perturbations)) (caaar (hash-ref (caar (hash-ref zo 'perturbations)) 'primes)))))]
         [f-plus (func plus-params)]
         [minus-params (list-set params dim (- orig (* (caar (hash-ref zo 'perturbations)) (caaar (hash-ref (caar (hash-ref zo 'perturbations)) 'primes)))))]
         [f-minus (func minus-params)])
    (list-set! params dim orig)
    (/ (- f-plus f-minus) (* 2.0 (caar (hash-ref zo 'perturbations)) (caaar (hash-ref (caar (hash-ref zo 'perturbations)) 'primes))))))

(define (estimate-gradient zo params func)
