    (for/list ([i (in-range (length params))]
               [g grad]
               [ao (hash-ref zo 'astro-offset)])
      (- (list-ref params i) (* g 1e-4 ao)))))

(define (objective-func params)
  (apply - (map (lambda (p) (* (sin p) (cos p) 0.01)) params)))

(define (train-celestial-zo zo initial-params iterations)
