-- DMSNN Stability Proofs in Lean 4
import Mathlib.Data.Real.Basic
import Mathlib.Tactic
import Mathlib.Algebra.BigOperators.Basic
import Mathlib.Analysis.NormedSpace.Basic

noncomputable section

open Real BigOperators Set

variable {V : Type*} [NormedSpace ℝ V] [CompleteSpace V]
variable {f : V → ℝ} [Continuous f]
variable {α : Type*} [MeasurableSpace α] [SigmaFinite α]
variable {μ : Measure α} [IsFiniteMeasure μ]

def bounded_potential (c : ℝ) (x : V) : Prop := ‖x‖ ≤ c

def spiking_stable (τ : ℝ) (g : V → V) : Prop :=
  ∀ x, bounded_potential τ x → bounded_potential τ (g x)

lemma lipchitz_continuity {L : ℝ} (hg : ∀ x y, ‖g x - g y‖ ≤ L * ‖x - y‖) :
  Continuous g := by
  intro x
  apply continuous_of_lipschitz hg

def diffusive_invariant (δ : ℝ) (d : V → V) : Prop :=
  ∀ x, 0 ≤ δ → ∀ t, ‖d (t • x)‖ ≤ δ * ‖x‖

lemma memristor_resistance_bound (r : ℝ) (v : ℝ) :
  0 < v → 0 < exp (-v) ∧ exp (-v) ≤ 1 := by
  intro hv
  constructor
  · exact exp_pos (-v)
  · apply exp_le_one
    linarith

lemma neuron_update_bound (tc dr : ℝ) (input : ℝ) (m : ℝ) (dt : ℝ) (qn : ℝ) :
  tc > 0 → dr ≥ 0 → 0 ≤ dt ≤ 1 → |qn| ≤ 1 → |input| ≤ 1 →
  |m + input - m * (dt / tc) + dr * qn * 0.01| ≤ max(|m|, 1) + 0.01 := by
  intros htc hdr hdt hqn hinp
  calc
    |m + input - m * (dt / tc) + dr * qn * 0.01|
    ≤ |m + input - m * (dt / tc)| + |dr * qn * 0.01|
    by norm_num; apply abs_add
    ... ≤ |m| * |1 - dt / tc| + |input| + |dr| * |qn| * 0.01
    by apply abs_sub_le; norm_num; apply abs_add_le_abs_abs
    ... ≤ |m| * (1 + dt / tc) + 1 + |dr| * 1 * 0.01
    by linarith [abs_nonneg _]; linarith [hqn]; ring_nf
    ... ≤ |m| * (1 + 1 / tc) + 1 + 0.01
    by linarith [hdt, htc]; ring_nf
    ... ≤ max(|m|, 1) + 1 / tc + 1.01
    by linarith [abs_le.mpr ⟨le_max_of_le_left (abs_nonneg _), le_max_of_le_right (by norm_num)⟩]
    ... ≤ max(|m|, 1) + 1 + 1.01
    by linarith [by norm_num : 0 < tc]

def dmsnn_layer_forward (n : ℕ) (W : Matrix ℝ n n) (b : Fin n → ℝ) (x : Fin n → ℝ) :
  Fin n → ℝ :=
  fun i => ∑ j, W i j * x j + b i

lemma layer_lipchitz {n : ℕ} {L : ℝ} (hW : ∀ i j, |W i j| ≤ L) (hb : ∀ i, |b i| ≤ L) (hx : ∀ i, |x i| ≤ 1) :
  ∀ i, |dmsnn_layer_forward n W b x i| ≤ n * L + L := by
  intro i
  calc |∑ j, W i j * x j + b i|
    = |∑ j, W i j * x j| + |b i|
    by rw [← add_abs]; norm_num
    ... ≤ ∑ j, |W i j * x j| + L
    by linarith [hb i]
    ... ≤ ∑ j, |W i j| * |x j| + L
    by apply Finset.sum_le_sum; intro j _; exact abs_mul_le
    ... ≤ ∑ j, L * 1 + L
    by apply Finset.sum_le_sum; intro j _; linarith [hW i j, hx j]
    ... = n * L + L
    by simp [Finset.card_finset_range]

def spiking_dynamics (τ : ℝ) (g : V → V) (x : V) : V :=
  if ‖g x‖ ≥ τ then 0 else g x

lemma dynamics_stability (τ : ℝ) (hg : LipchitzWith 1 g) (hτ : 0 < τ) :
  spiking_stable τ (spiking_dynamics τ g) := by
  intro x hx
  rw [spiking_stable, bounded_potential]
  by_cases hgx : ‖g x‖ ≥ τ
  · simp [spiking_dynamics, hgx]; norm_num
  · simp [spiking_dynamics, hgx]
    rw [norm_zero]
    exact hτ

def quantum_noise_injection (σ : ℝ) (r : V → V) (x : V) : V :=
  x + σ * (Uniform (ball x 1) 0).sample

lemma noise_bounded_variation (σ : ℝ) (hr : LipchitzWith 1 r) (hσ : 0 ≤ σ ≤ 1) :
  LipchitzWith (1 + σ) (quantum_noise_injection σ r) := by
  intro x y
  calc ‖quantum_noise_injection σ r x - quantum_noise_injection σ r y‖
    ≤ ‖r x - r y‖ + σ * ‖sample_x - sample_y‖
    by apply norm_add_le
    ... ≤ ‖x - y‖ + σ * 2
    by linarith [hr x y]; norm_num [Uniform.ball_diam]
    ... ≤ (1 + σ) * ‖x - y‖
    by linarith [hσ]

-- Full DMSNN stability: composition of layers
def dmsnn_stable (k : ℕ) (L : ℝ) (layers : List (V → V)) : Prop :=
  ∀ (i : ℕ), i < k → LipchitzWith L (layers.get? i |>.getD (id))

