// PhotonicInterference.scala - SpinalHDL for photonic circuits
import spinal.core._
import spinal.lib._
import spinal.lib.fsm._

case class InterferenceGate() extends Component {
  val io = new Bundle {
    val inputA = in Bits(32 bits)
    val inputB = in Bits(32 bits)
    val phaseShift = in SInt(16 bits)
    val output = out Bits(32 bits)
  }

  val beamSplitter = new Area {
    val splitA = (io.inputA.asSInt + io.inputB.asSInt) >> 1
    val splitB = (io.inputA.asSInt - io.inputB.asSInt) >> 1
    val modulatedA = (splitA + io.phaseShift).asBits
    val modulatedB = splitB.asBits
    io.output := (modulatedA | modulatedB).asBits
  }
}

case class PhotonicMemristor(nNeurons: Int = 1024) extends Component {
  val io = new Bundle {
    val weights = in Vec(Bits(16 bits), nNeurons)
    val inputs = in Vec(Bits(16 bits), nNeurons)
    val conductances = in Vec(SFix(8, 4, fixto="sfix"), nNeurons)
    val output = out Vec(Bits(32 bits), nNeurons)
  }

  val interferences = for (i <- 0 until nNeurons) yield {
    val gate = InterferenceGate()
    gate.io.inputA := io.inputs(i).resize(32)
    gate.io.inputB := io.weights(i).resize(32)
    gate.io.phaseShift := io.conductances(i).raw
    gate.io.output
  }

  io.output := Vec(interferences)
}

case class DiffusivePhotonicArray(nLayers: Int = 12, nNeurons: Int = 18432) extends Component {
  val io = new Bundle {
    val input = slave Flow(Vec(Bits(32 bits), nNeurons))
    val weightsAll = in Vec(Vec(Bits(16 bits), nNeurons), nLayers)
    val biases = in Vec(Vec(Bits(16 bits), nNeurons), nLayers)
    val dt = in SFix(8, 4, fixto="sfix")
    val qNoise = in SFix(8, 4, fixto="sfix")
    val output = master Flow(Vec(Bits(32 bits), nNeurons))
  }

  val layers = for (l <- 0 until nLayers) yield {
    val memristor = PhotonicMemristor(nNeurons)
    memristor.io.weights := io.weightsAll(l)
    memristor.io.inputs := if (l == 0) io.input.payload else layers(l-1).output.payload
    memristor.io.conductances := Vec.tabulate(nNeurons, _ => SFix(1.0))
    memristor.io.output
  }

  io.output.payload := layers.last
  io.output.valid := io.input.valid
}

object PhotonicSim extends App {
  SpinalVerilog(PhotonicMemristor(1024))
  SpinalVerilog(DiffusivePhotonicArray())
}

