case class QuantumIPC(nQubits: Int = 156) extends Component {
  val io = new Bundle {
    val qubitStates = in Vec(Bool, nQubits)
    val gates = in Vec(Bits(8 bits), nQubits)
    val measurement = out Vec(Bool, nQubits)
  }

  val hadamards = Vec.tabulate(nQubits, i => {
