theory MemristorSafety
  imports Main "HOL-Real" "HOL-Library.Lattice_Syntax"
begin

section "Memristor Resistance Bounds"

definition memristor_resistance :: "real \<Rightarrow> real" where
  "memristor_resistance v = exp(-v)"

lemma memristor_pos: "v \<ge> 0 \<Longrightarrow> memristor_resistance v > 0"
  by (simp add: memristor_resistance_def exp_gt_zero)

lemma memristor_le_one: "v \<ge> 0 \<Longrightarrow> memristor_resistance v \<le> 1"
  apply (simp add: memristor_resistance_def)
  apply (rule exp_le_one)
  by simp

section "Neuron Update Bounds"

record neuron_state =
  membrane :: real
  threshold :: real
  reset :: real
  refractory :: nat
  conductance :: real
  diffusion :: real
  quantum_noise :: real
  astro_mod :: real
  mem_res :: real
  time_const :: real
  diff_rate :: real

definition update_neuron :: "real \<Rightarrow> real \<Rightarrow> real \<Rightarrow> neuron_state \<Rightarrow> neuron_state" where
  "update_neuron input dt qn s =
   let new_qn = qn;
       new_mem = membrane s + input - membrane s * (dt / time_const s) + diff_rate s * new_qn * 0.01;
       new_mem_mod = new_mem * (astro_mod s / conductance s * mem_res s);
       new_mem_res = memristor_resistance new_mem_mod;
       new_ref = (if new_mem_mod >= threshold s then 5 else if refractory s > 0 then refractory s - 1 else 0);
       final_mem = (if new_mem_mod >= threshold s then reset s else if refractory s > 0 then reset s else new_mem_mod);
       new_diff = final_mem * dt * 0.05 + new_qn * 0.02;
       new_cond = (if new_mem_mod >= threshold s then 1.2 else conductance s)
   in NeuronState final_mem (threshold s) (reset s) new_ref new_cond new_diff new_qn (astro_mod s) new_mem_res (time_const s) (diff_rate s)"

lemma bounded_update:
  assumes "abs input \<le> 1" "0 \<le> dt" "dt \<le> 1" "abs qn \<le> 1" "time_const s > 0" "diff_rate s \<ge> 0"
    "abs (membrane s) \<le> c" "c \<ge> 0"
  shows "abs (membrane (update_neuron input dt qn s)) \<le> max c (1 + 1 / time_const s + 0.01)"
proof -
  have "abs new_mem \<le> abs (membrane s) + abs input + abs (membrane s * (dt / time_const s)) + abs (diff_rate s * qn * 0.01)"
    unfolding update_neuron_def Let_def
    by (simp add: abs_triangle_ineq4 abs_triangle_ineq abs_mult)
  also have "... \<le> c + 1 + c * (dt / time_const s) + diff_rate s * 1 * 0.01"
    using assms abs_mult_le by (simp add: mult.commute)
  also have "... \<le> c + 1 + c * (1 / time_const s) + 0.01"
    using assms by (simp add: mult_left_mono)
  also have "... \<le> max c (1 + 1 / time_const s + 0.01) + c / time_const s"
    by (simp add: max_def split: split_max)
  finally show ?thesis .
qed

section "Layer Lipschitz Continuity"

definition layer_forward :: "nat \<Rightarrow> (nat \<Rightarrow> nat \<Rightarrow> real) \<Rightarrow> (nat \<Rightarrow> real) \<Rightarrow> (nat \<Rightarrow> real) \<Rightarrow> (nat \<Rightarrow> real)" where
  "layer_forward n W b x i = (\<Sum>j<n. W i j * x j) + b i"

lemma layer_lip: fixes n :: nat assumes "∀i j. abs (W i j) \<le> L" "∀i. abs (b i) \<le> L" "∀i < n. abs (x i) \<le> 1"
  shows "∀i < n. abs (layer_forward n W b x i) \<le> of_nat n * L + L"
  unfolding layer_forward_def
  by (simp add: abs_triangle_ineq4 sum_distrib abs_triangle_ineq abs_mult_le assms of_nat_def)

section "Full DMSNN Stability"

definition dmsnn_stable :: "nat \<Rightarrow> real \<Rightarrow> ((nat \<times> (real \<times> real)) list) \<Rightarrow> bool" where
  "dmsnn_stable k L layers = (∀i < k. let (n, (Wl, bl)) = layers ! i in layer_lip n Wl bl)"

theorem convergence_stability: fixes k :: nat assumes "dmsnn_stable k 1 layers" "∀inputs. abs inputs \<le> 1"
  shows "∃c. ∀states, ∀n, bounded_update c states n"
  using assms sorry

end
