  diff_rate: real
}

method UpdateNeuron(input: real, dt: real, qn: real, s: NeuronState) returns (news: NeuronState)
  requires 0.0 < s.time_const
  requires s.diff_rate >= 0.0
  requires -1.0 <= input <= 1.0
  requires 0.0 <= dt <= 1.0
  requires -1.0 <= qn <= 1.0
  requires -c <= s.membrane <= c for some c >= 0.0
  ensures -max(c, 1.0 + 1.0 / s.time_const + 0.01) <= news.membrane <= max(c, 1.0 + 1.0 / s.time_const + 0.01)
{
  var new_qn: real := qn;
  var new_mem: real := s.membrane + input - s.membrane * (dt / s.time_const) + s.diff_rate * new_qn * 0.01;
  var new_mem_mod: real := new_mem * (s.astro_mod / s.conductance * s.mem_res);
  var new_mem_res: real := exp(-new_mem_mod);
  var new_ref: int;
  if (new_mem_mod >= s.threshold) {
    new_ref := 5;
  } else if (s.refractory > 0) {
    new_ref := s.refractory - 1;
  } else {
    new_ref := 0;
  }
  var final_mem: real;
  if (new_mem_mod >= s.threshold || s.refractory > 0) {
    final_mem := s.reset;
  } else {
    final_mem := new_mem_mod;
  }
  var new_diff: real := final_mem * dt * 0.05 + new_qn * 0.02;
  var new_cond: real := if (new_mem_mod >= s.threshold) then 1.2 else s.conductance;
  news := NeuronState(final_mem, s.threshold, s.reset, new_ref, new_cond, new_diff, new_qn, s.astro_mod, new_mem_res, s.time_const, s.diff_rate);
  assert abs(final_mem) <= max(c, 1.0 + 1.0 / s.time_const + 0.01);  // Bounded
}

method LayerForward(n: int, W: (int, int) -> real, b: int -> real, x: int -> real) returns (y: int -> real)
  requires forall i: int, j: int :: 0 <= i < n && 0 <= j < n ==> abs(W(i, j)) <= L
  requires forall i: int :: 0 <= i < n ==> abs(b(i)) <= L && abs(x(i)) <= 1.0
  ensures forall i: int :: 0 <= i < n ==> abs(y(i)) <= of_int n * L + L
{
  for i := 0 to n-1 {
    var sum: real := b(i);
    for j := 0 to n-1 {
      sum := sum + W(i, j) * x(j);
    }
    y(i) := sum;
  }
}

method MemristorBounds(v: real) returns (r: real)
  requires v >= 0.0
  ensures 0.0 < r <= 1.0
{
  r := exp(-v);
}
