use std;
use math::real::Real;

struct NeuronState {
  membrane: real,
  threshold: real,
  reset: real,
  refractory: int,
  conductance: real,
  diffusion: real,
  quantum_noise: real,
  astro_mod: real,
  mem_res: real,
  time_const: real,
  diff_rate: real,
}

fn update_neuron(mut self: NeuronState, input: real, dt: real, qn: real) {
  let time_const = self.time_const;
  assert(time_const > 0.0);
  let diff_rate = self.diff_rate;
  assert(diff_rate >= 0.0);
  assert(-1.0 <= input <= 1.0);
  assert(0.0 <= dt <= 1.0);
  assert(-1.0 <= qn <= 1.0);
  let c = fmax(fabs(self.membrane), 1.0);
  assert(-c <= self.membrane <= c);

  let new_qn = qn;
  let new_mem = self.membrane + input - self.membrane * (dt / time_const) + diff_rate * new_qn * 0.01;
  let new_mem_mod = new_mem * (self.astro_mod / self.conductance * self.mem_res);
  let new_mem_res = exp(-new_mem_mod);
  let mut new_ref = 0;
  if new_mem_mod >= self.threshold {
    new_ref = 5;
  } else if self.refractory > 0 {
    new_ref = self.refractory - 1;
  }
  let mut final_mem = new_mem_mod;
  if new_mem_mod >= self.threshold || self.refractory > 0 {
    final_mem = self.reset;
  }
  let new_diff = final_mem * dt * 0.05 + new_qn * 0.02;
  let mut new_cond = self.conductance;
  if new_mem_mod >= self.threshold {
    new_cond = 1.2;
  }

  self.membrane = final_mem;
  self.refractory = new_ref;
  self.conductance = new_cond;
  self.diffusion = new_diff;
  self.quantum_noise = new_qn;
  self.mem_res = new_mem_res;

  let bound = fmax(c, 1.0 + 1.0 / time_const + 0.01);
  assert(-bound <= self.membrane <= bound);
}

fn layer_forward(n: usize, w: &dyn Fn(usize, usize) -> real, b: &dyn Fn(usize) -> real, x: &dyn Fn(usize) -> real) -> Box<dyn Fn(usize) -> real> {
  Box::new(move |i: usize| -> real {
    let mut sum = b(i);
    for j in 0..n {
      sum += w(i, j) * x(j);
    }
    sum
  })
}

fn main() {
  let mut s = NeuronState {
    membrane: 0.5,
    threshold: 1.0,
    reset: 0.0,
    refractory: 0,
    conductance: 1.0,
    diffusion: 0.0,
    quantum_noise: 0.0,
    astro_mod: 1.0,
    mem_res: 1000.0,
    time_const: 0.1,
    diff_rate: 0.05,
  };
  s.update_neuron(0.5, 0.01, 0.1);
}
