/* Spiking Dynamics Model in Promela */
#define NUM_NEURONS 18432
#define NUM_LAYERS 12
#define TIME_STEPS 100
#define BATCH_SIZE 128
#define MAX_FAIL 5

byte states[NUM_LAYERS][NUM_NEURONS];  /* Membrane potentials */
byte gradients[BATCH_SIZE];           /* Per batch gradients */
byte step = 0;
byte active_nodes = 8;                 /* B200 x8 */
byte failed = 0;
byte dt = 1;                           /* 0.01 scaled */
byte qn = 10;                          /* 0.1 scaled */

#define BOUNDED(v, c) ((v >= -c) && (v <= c))

active proctype NeuronLayer(byte layer) {
  byte i, mem, input, new_mem;
  do
  :: true ->
    for(i : 0 .. NUM_NEURONS-1) {
      input = (step % 10) - 5;  /* -5..5 scaled from -0.5..0.5 */
      mem = states[layer][i];
      if
      :: (mem + input - mem * (dt / 10) + (qn / 10)) >= 100 ->  /* Threshold 1.0 scaled */
        states[layer][i] = 0;  /* Reset */
      :: else ->
        new_mem = mem + input - mem * (dt / 10) + (qn / 10);
        assert(BOUNDED(new_mem, 100));  /* Bounded invariant */
        states[layer][i] = new_mem;
      fi;
    }
    step++;
    if
    :: (step % 100 == 0) -> 
      gradients[0] = 1;  /* Dummy gradient */
      for(i : 0 .. NUM_NEURONS-1) {
        states[layer][i] -= gradients[0];  /* Update */
      }
    fi;
  od;
}

active proctype Heartbeat() {
  do
  :: true ->
    if
    :: (random() % 10 == 0) ->  /* Simulate failure */
      active_nodes--;
      failed++;
      if
      :: (failed > MAX_FAIL) ->
        assert(false);  /* Liveness violation */
      :: else ->
        skip;
      fi;
    :: else ->
      skip;
    fi;
    assert(active_nodes >= 1);
  od;
}

init {
  byte i, j;
  for(i : 0 .. NUM_LAYERS-1) {
    for(j : 0 .. NUM_NEURONS-1) {
      states[i][j] = 50;  /* Initial 0.5 scaled */
    }
  }
  run NeuronLayer(1);
  run NeuronLayer(2);
  run Heartbeat();
}
