require "json"
require "http/client"
require "time"

struct AstroParams
  property declination : Float64, right_ascension : Float64, julian_day : Float64
end

class ModalInit
  @config : JSON::Any
  @gpu_count : Int32 = 8

  def initialize(config_path : String)
    @config = File.read(config_path).to_json_any
  end

  def julian_day
    now = Time.utc.to_unix_f / 86400.0 + 2440587.5
    now
  end

  def init_params
    params = AstroParams.new(
      declination: 45.0,
      right_ascension: 90.0,
      julian_day: julian_day
    )
    embed = compute_embed(params)
    noise = quantum_noise(params, 156)
    data = {
      "embed" => embed.to_a,
      "noise" => noise.to_a,
      "knots" => compute_knots(params.julian_day).to_a
    }
    File.write("build/astro_params.json", data.to_json)
    puts "Initialized: embed size #{embed.size}, noise len #{noise.size}"
  end

  private def compute_embed(params : AstroParams)
    embed = Array(Array(Float64)).new(50000) { |i|
      Array(Float64).new(3) { |f|
        let mod_e = i % 1000
        let k_idx = i % 7
        let traj = lorenz_traj(params, 1000)
        traj[mod_e][f] * knots[params.julian_day][k_idx]
      }
    }
    embed
  end

  private def lorenz_traj(params, steps)
    traj = Array(Array(Float64)).new(steps) { |s| Array(Float64).new(3, &.[0.0]) }
    traj[0] = [Math.sin(params.declination * Math::PI / 180.0),
               Math.cos(params.right_ascension * Math::PI / 180.0), 0.0]
    dt = 0.01
    sigma, rho, beta = 10.0, 28.0, 8.0/3.0
    steps.times do |s|
      if s > 0
        x, y, z = traj[s-1]
        dx = sigma * (y - x) * dt
        dy = (x * (rho - z) - y) * dt
        dz = (x * y - beta * z) * dt
        traj[s] = [x + dx, y + dy, z + dz]
      end
    end
    traj
  end

  private def compute_knots(jd)
    angle = jd * 2 * Math::PI / 365.25
    sin_a = Math.sin(angle)
    cos_a = Math.cos(angle)
    (0..6).map { |i| (i.to_f * (sin_a + cos_a * i.to_f)) }
  end

  private def quantum_noise(params, shots)
    knots = compute_knots(params.julian_day)
    traj = lorenz_traj(params, 1000)
    (0...shots).map do |s|
      phase = traj[s % 1000][1] * (1.0 + rand(-0.1..0.1))
      Math.sin(phase) * knots[s % 7]
    end
  end

  def deploy_modal
    token = @config["modal_token"].as_s
    url = ""
    body = {
      "image" => "jaide/v41-runtime:latest",
      "command" => ["/bin/train", "--gpus", @gpu_count.to_s],
      "replicas" => @gpu_count,
      "gpu" => "b200"
    }.to_json

    HTTP::Client.post(url, headers: HTTP::Headers{"Authorization" => "Bearer #{token}", "Content-Type" => "application/json"}, body: body)
    puts "Modal job submitted for B200 x#{@gpu_count}"
  end

  def run
    init_params
    deploy_modal
  end
