// memristorneuron.v - Generated from Clash
// Diffusive Memristor Array for Ice40 HX8K

module memristorneuron (
    input wire clk,
    input wire rst,
    input wire en,
    input wire [7:0] input_current,
    output reg [7:0] output_spike
);

    reg [15:0] membrane = 0;
    reg [15:0] threshold = 1024;  // 1.0 scaled to 16-bit
    reg [15:0] reset_pot = 0;
    reg [3:0] refractory = 0;
    reg [15:0] conductance = 1024;  // 1.0
    reg [15:0] diffusion = 0;
    reg [15:0] quantum_noise = 0;
    reg [15:0] astro_mod = 1024;  // 1.0
    reg [15:0] mem_res = 102400;   // 1000.0 scaled
    reg [15:0] time_const = 102;   // 0.1 scaled
    reg [15:0] diff_rate = 51;     // 0.05 scaled
    reg [31:0] dt_fixed = 10;      // 0.01 scaled

    wire [31:0] leak;
    wire [31:0] update_term;
    wire [31:0] diff_term;
    wire [31:0] mod_term;
    wire [31:0] new_mem_mod;
    wire [31:0] exp_arg;
    wire [31:0] new_mem_res;
    wire spike;
    wire reset_mem;
    reg [31:0] new_diff;

    // Fixed-point arithmetic (Q16.16)
    assign leak = (membrane * dt_fixed) / time_const;
    assign update_term = (input_current * 256) - leak + (diff_rate * quantum_noise * 3) / 256;  // 0.01 scaled
    assign membrane_next = membrane + update_term[15:0];

    assign diff_term = (diff_rate * quantum_noise * 3) / 256;
    assign diffusion = diffusion + diff_term[15:0];

    assign mod_term = (astro_mod * mem_res) / conductance;
    assign new_mem_mod = membrane_next * mod_term;

    assign exp_arg = -new_mem_mod;
    assign new_mem_res = exp_approx(exp_arg);  // Custom exp function

    assign spike = (new_mem_mod >= threshold);
    assign reset_mem = spike || (refractory > 0);

    always @(posedge clk) begin
        if (rst) begin
            membrane <= 0;
            refractory <= 0;
            conductance <= 1024;
            diffusion <= 0;
            quantum_noise <= 512;  // 0.5
            mem_res <= 102400;
            output_spike <= 0;
        end else if (en) begin
            quantum_noise <= lfsr_next(quantum_noise);  // Simple LFSR noise
            if (reset_mem) begin
                membrane <= reset_pot;
                if (spike) begin
                    refractory <= 5;
                    conductance <= 1229;  // 1.2
                end else begin
                    refractory <= refractory - 1;
                end
            end else begin
                membrane <= new_mem_mod[15:0];
            end
            diffusion <= new_diff[15:0];
            mem_res <= new_mem_res[15:0];
            output_spike <= spike ? 255 : 0;
        end
    end

    // Approximate exp using Taylor series (up to 4 terms for efficiency)
    function [31:0] exp_approx;
        input [31:0] x;
        reg [31:0] x2, x3, x4;
        reg [31:0] term1, term2, term3, term4;
        begin
            x2 = x * x / 65536;
            x3 = x2 * x / 65536;
            x4 = x3 * x / 65536;
            term1 = x;
            term2 = x2 / 2;
            term3 = x3 / 6;
            term4 = x4 / 24;
            exp_approx = 65536 + term1 + term2 + term3 + term4;  // e^0 = 1.0 scaled
        end
    endfunction

    // 16-bit LFSR for quantum noise
    function [15:0] lfsr_next;
        input [15:0] seed;
        reg [15:0] next;
        begin
            next = seed ^ (seed >> 7) ^ (seed >> 12) ^ (seed >> 15);
            next = next | 1;  // Ensure non-zero
            lfsr_next = next % 1024;  // Bound to [-0.5, 0.5] scaled
        end
    endfunction

    // New diffusion computation
    always @(*) begin
        new_diff = new_mem_mod * dt_fixed * 5 / 256 + quantum_noise * 2 / 100;
    end

