/* Additional Spin model for distributed sync */
mtype = {SPike, RESET, UPDATE, FAIL};

chan layer_chans[NUM_LAYERS] = [NUM_NEURONS] of {mtype, byte};
chan heartbeat = [8] of {mtype};

proctype DistributedSync(byte node) {
  byte mem = 50;  /* Initial state */
  do
  :: true ->
    heartbeat?UPDATE ->
      /* Simulate compute */
      if
      :: mem >= 100 -> layer_chans[node]!SPike, mem; mem := 0;
      :: else -> mem := mem + random(10); layer_chans[node]!UPDATE, mem;
      fi;
    :: (random() % 100 == 0) ->
      heartbeat!FAIL;  /* Node failure */
      break;
  od;
}

init {
  byte i;
  atomic {
    for(i : 0 .. NUM_LAYERS-1) {
      run DistributedSync(i);
    }
    run HeartbeatMonitor();
  }
}

proctype HeartbeatMonitor() {
  byte fails = 0;
  do
  :: true ->
    heartbeat?FAIL -> fails++;
    if
    :: (fails > 5) -> assert(false);  /* Too many failures */
    :: else -> skip;
    fi;
  od;
}
