astroInfluence :: Double -> Double -> Double -> Params -> Double
astroInfluence dec ra jd params = sum [p * sin (dec * pi / 180 + i * jd * ra) | (p, i) <- zip params [0..]]

optimizeGeomantic :: Double -> Double -> Double -> Params -> Params
optimizeGeomantic dec ra jd initParams = grad' (astroInfluence dec ra jd) initParams

main :: IO ()
