# src/adaptive_pruner.nim
# Adaptive model pruning with spectral norm
import std/[math, random, sequtils, tables, locks, atomics]
import std/parallel

type
  PruneMask = seq[bool]
  SpectralNorm = float

proc spectral_norm(weights: seq[float], k: int = 10): SpectralNorm =
  # Power iteration for approx spectral norm
  var v = newSeq[float](weights.len)
  for i in 0..<v.len: v[i] = rand(1.0)
  for _ in 0..<k:
    let wv = mul_mv(weights, v)
    v = normalize(wv)
    let norm = dot(v, wv)
  result = sqrt(abs(norm))

proc adaptive_prune(weights: seq[float], threshold: float = 0.01, ratio: float = 0.1): PruneMask =
  let norm = spectral_norm(weights)
  let scaled_thresh = threshold * norm
  result = newSeq[bool](weights.len)
  var count = 0
  for i, w in pairs(weights):
    if abs(w) < scaled_thresh:
      result[i] = true
      inc count
    else:
      result[i] = false
  let actual_ratio = float(count) / float(weights.len)
  if actual_ratio < ratio:
    # Adjust threshold dynamically
    let new_thresh = scaled_thresh * (ratio / actual_ratio)
    for i, w in pairs(weights):
      result[i] = abs(w) < new_thresh

proc apply_mask(weights: var seq[float], mask: PruneMask) =
  for i in 0..<weights.len:
    if mask[i]:
      weights[i] = 0.0

proc parallel_prune(weights_table: Table[string, seq[float]], num_threads: int) =
  parallel:
    for key, weights in pairs(weights_table):
      let mask = adaptive_prune(weights)
      weights.apply_mask(mask)
      echo "Pruned ", key, " with ratio ", count_true(mask) / weights.len

when isMainModule:
  randomize()
  var table = initTable[string, seq[float]]()
  for i in 0..<10:
    table[fmt"layer_{i}"] = newSeq[float](1024)
    for j in 0..<1024:
      table[fmt"layer_{i}"][j] = rand(-1.0..1.0)
  parallel_prune(table, 4)
