open import std

entry quantum_noise_kernel (shots: i64, knots: [astro_knots]f64, jd: f64) : [shots]f64 =
  let pi = 3.141592653589793 : f64
  let phase = jd * 2.0 * pi / 365.25
  in
  map (\s ->
         let s_f64 = f64.i64 s
         let knot_idx = i64.i64 (s % astro_knots)
         let noise = sin(s_f64 * phase) * knots[knot_idx] + 0.01 * gaussian 0.0 1.0
         in noise,
       iota shots)

-- Astro knot computation
let astro_knots_comp (jd: f64) : [7]f64 =
  let pi = 3.141592653589793 : f64
  let angle = jd * 2.0 * pi / 365.25
  let sin_a = sin angle
  let cos_a = cos angle
  in
  map (\i -> f64.i64 i * (sin_a + cos_a * f64.i64 i), iota 7)

entry coupled_kernel (shots: i64, jd: f64, dec: f64, ra: f64) : [shots]f64 =
  let knots = astro_knots_comp jd
  let pi = 3.141592653589793 : f64
  let mod_factor = sin(dec * pi / 180.0) * cos(ra * pi / 180.0)
  let noise = quantum_noise_kernel shots knots jd
  in
  map (\n -> n * mod_factor, noise)

-- Test entry
entry test_coupling (jd: f64) : f64 =
  let noise = coupled_kernel 156 jd 45.0 90.0
  let sum = reduce_comm (+, 0.0) noise
  in sum / f64.i64 156
