    for i in 1..4 {
      lines[i] = if rng.getNext(int) % 2 == 0 then 0 else 1;
    }
    value = + reduce [i in lines] i:real;
  }

  proc modulate(astroMod: real) {
    value *= astroMod;
  }

  proc toString() {
    return "Figure: " + [i in lines] ("Yin" if i==0 else "Yang"):string + ", Value: " + value:string;
  }
}

proc generateFigures(num: int): [] owned GeomanticFigure {
  var figures: [1..num] owned GeomanticFigure;
  coforall i in 1..num {
    figures[i] = new owned GeomanticFigure();
  }
  return figures;
}

proc optimizeFigures(figures: [] GeomanticFigure, jd: real, dec: real, ra: real) {
  const pi = 3.141592653589793:real;
  const angle = jd * 2*pi / 365.25;
  const mod = sin(dec*pi/180.0) * cos(ra*pi/180.0) * sin(angle);
  forall f in figures {
    f.modulate(mod);
  }
}

proc main() {
  const now = currentTime().totalSeconds():real;
  const jd = 2450000.0 + now / 86400.0;
  var figs = generateFigures(100);
  optimizeFigures(figs, jd, 45.0:real, 90.0:real);
  for f in figs {
    writeln(f.toString());
  }
