    totalValue <== totalSum.out;

    // Constraint: value bounded
    signal bound;
    bound <== totalValue * (1.0 - totalValue / nFigures * 4.0);  // Max value 4*n
    bound === 0.0;

    // JD modulation constraint
    component modCheck = Multiplier();
    modCheck.a <== jd * 2 * 3.14159 / 365.25;
