-- src/geomantic_invariants.lean
import Mathlib.Data.Nat.Basic
import Mathlib.Data.Bool.Basic
import Mathlib.Tactic

inductive GeomanticLine : Type
| yin : GeomanticLine
| yang : GeomanticLine
deriving DecidableEq

structure GeomanticFigure where
  lines : List GeomanticLine
  deriving Repr

def figureValue (fig : GeomanticFigure) : Nat :=
  fig.lines.lengthFilter (· = GeomanticLine.yang)

def astroModulation (dec ra jd : ℝ) : ℝ :=
  Real.sin (dec * Real.pi / 180) * Real.cos (ra * Real.pi / 180) * Real.sin (jd * 2 * Real.pi / 365.25)

def modulateFigure (fig : GeomanticFigure) (mod : ℝ) : ℝ :=
  figureValue fig + mod

lemma value_nonneg (fig : GeomanticFigure) : 0 ≤ figureValue fig := by
  unfold figureValue
  apply List.lengthFilter_nonneg

lemma modulation_bounded (dec : ℝ) (h_dec : -90 ≤ dec ≤ 90)
  (ra : ℝ) (h_ra : 0 ≤ ra ≤ 360) (jd : ℝ) (h_jd : 2450000 ≤ jd ≤ 2460000) :
  |astroModulation dec ra jd| ≤ 2 := by
  unfold astroModulation
  have h1 : |Real.sin (dec * Real.pi / 180)| ≤ 1 := Real.sin_le_one _
  have h2 : |Real.cos (ra * Real.pi / 180)| ≤ 1 := Real.cos_le_one _
  have h3 : |Real.sin (jd * 2 * Real.pi / 365.25)| ≤ 1 := Real.sin_le_one _
  calc
    |Real.sin (dec * Real.pi / 180) * Real.cos (ra * Real.pi / 180) * Real.sin (jd * 2 * Real.pi / 365.25)|
    ≤ 1 * 1 * 1 := by linarith [h1, h2, h3]
    ... = 1 := rfl

lemma modulated_value_bounded (fig : GeomanticFigure) (mod : ℝ) (h_mod : |mod| ≤ 2) :
  |modulateFigure fig mod| ≤ figureValue fig + 2 := by
  unfold modulateFigure
  rw [abs_add]
  apply add_le_add
  · exact value_nonneg fig
  · linarith [h_mod]

def generateFigure (seed : Nat) : GeomanticFigure :=
  { lines := List.replicate 4 (if seed % 2 = 0 then GeomanticLine.yin else GeomanticLine.yang) }

example : ∀ fig mod, |mod| ≤ 2 → |modulateFigure fig mod| ≤ 4 + 2 := by
  intros fig mod h_mod
  have h_fig : figureValue fig ≤ 4 := by
    unfold figureValue
    simp [List.lengthFilter_le_length]
  have h : |modulateFigure fig mod| ≤ figureValue fig + 2 := modulated_value_bounded fig mod h_mod
  linarith [h, h_fig]
