case class PhotonicQubit(nQubits: Int = 156) extends Component {
  val io = new Bundle {
    val states = in Vec(Bool, nQubits)
    val phase = in SFix(16, 8 bits)
    val measurement = out Vec(SFix(16, 8 bits), nQubits)
  }

