    phaseShifter := io.phase * SFix(0.1)
    val meas = (io.states(i).asSInt.resize(16) + phaseShifter.raw).asBits
    SFix.fromBits(meas.resize(16))
  })

  io.measurement := interferometers
}

case class AstroPhotonicCoupling() extends Component {
  val io = new Bundle {
    val jd = in SFix(32, 16 bits)
    val dec = in SFix(16, 8 bits)
    val ra = in SFix(16, 8 bits)
    val modulation = out SFix(16, 8 bits)
  }

  val pi = SFix(32 exp, 16 fp) (3.141592653589793)
  val angle = io.jd * SFix(2.0) * pi / SFix(365.25)
  val sin_dec = sin(io.dec * pi / SFix(180.0))
  val cos_ra = cos(io.ra * pi / SFix(180.0))
  val sin_angle = sin(angle)
  io.modulation := sin_dec * cos_ra * sin_angle
}

