import gleam/dynamic
import gleam/option.{Option}
import gleam/list
import gleam/bit_string
import gleam/float
import gleam/int
import gleam/result
import gleam/string
import gleam/json
import gleam/crypto
import gleam/erlang

pub type PrunedLayer {
  PrunedLayer(weights: Map(Int, Float), mask: List(Bool), norm: Float)
}

pub fn compute_spectral_norm(weights: List(Float)) -> Float {
  let n = list.length(weights)
  let v = list.map(list.range(0, n - 1), fn(_) { float.random_uniform(0.0, 1.0) })
  let iterations = 10
  list.fold(list.range(0, iterations), v, fn(acc_v, _) {
    let wv = matrix_vector_mul(weights, acc_v)
    normalize_vector(wv)
  })
  |> vector_norm
}

pub fn matrix_vector_mul(weights: List(Float), v: List(Float)) -> List(Float) {
  let n = list.length(weights)
  list.index_map(weights, fn(i, w) {
    let row_start = i * n
    list.slice(v, row_start, n) |> list.fold(0.0, fn(acc, x) { acc +. w *. x })
  })
}

pub fn normalize_vector(v: List(Float)) -> List(Float) {
  let norm = vector_norm(v)
  case norm >. 0.0 {
    True -> list.map(v, fn(x) { x /. norm })
    False -> v
  }
}

pub fn vector_norm(v: List(Float)) -> Float {
  v |> list.map(fn(x) { x *. x }) |> list.fold(0.0, fn(acc, x) { acc +. x }) |> float.sqrt
}

pub fn adaptive_prune(layer: PrunedLayer, threshold: Float, ratio: Float) -> PrunedLayer {
  let norm = compute_spectral_norm(layer.weights |> map.values |> list.from_list)
  let scaled_thresh = threshold *. norm
  let mask = list.map(layer.weights |> map.values |> list.from_list, fn(w) {
    float.abs(w) < scaled_thresh
  })
  let true_count = list.length(list.filter(mask, fn(b) { b }))
  let actual_ratio = float.from_int(true_count) /. float.from_int(list.length(mask))
  let new_thresh = case actual_ratio <. ratio {
    True -> scaled_thresh *. (ratio /. actual_ratio)
    False -> scaled_thresh
  }
  let new_mask = list.map(layer.weights |> map.values |> list.from_list, fn(w) {
    float.abs(w) < new_thresh
  })
  let pruned_weights = map.new()
  let indexed = list.index_map(layer.weights |> map.to_list, fn(kv, i) {
    let (k, v) = kv
    Tuple2(k, case list.at(new_mask, i) |> result.unwrap(False) {
      True -> 0.0
      False -> v
    })
  })
  list.fold(indexed, pruned_weights, fn(acc, kv) {
    let (k, v) = kv
    map.insert(acc, k, v)
  })
  PrunedLayer(pruned_weights, new_mask, norm)
}

test "spectral_norm" {
  let weights = [1.0, 0.5, 0.0, -0.5]
  compute_spectral_norm(weights)
  |> float.approximately(1.0, 0.1)
  |> should.equal(True)
}
