# src/zerotensor_py.py
# Python with Numba for zero-overhead tensors
import numba
from numba import jit, float64
import numpy as np
from math import sin, cos, pi
import json
from datetime import datetime

@jit(nopython=True)
def lorenz_tensor(steps, sigma=10.0, rho=28.0, beta=8.0/3.0, dt=0.01):
    traj = np.zeros((steps, 3))
    x, y, z = 1.0, 1.0, 1.0
    traj[0] = [x, y, z]
    for i in range(1, steps):
        dx = sigma * (y - x) * dt
        dy = (x * (rho - z) - y) * dt
        dz = (x * y - beta * z) * dt
        x += dx
        y += dy
        z += dz
        traj[i] = [x, y, z]
    return traj

@jit(nopython=True)
def astro_tensor_mul(traj, dec, ra, jd):
    angle = jd * 2 * pi / 365.25
    mod = sin(dec * pi / 180) * cos(ra * pi / 180) * sin(angle)
    return traj * mod

@numba.jit(nopython=True)
def evaluate_tensor_op(a, op, b):
    if op == 0:  # +
        return a + b
    elif op == 1:  # -
        return a - b
    elif op == 2:  # *
        return a * b
    return 0.0

class ZeroTensor:
    def __init__(self, op=None, args=()):
        self.op = op
        self.args = args if isinstance(args, tuple) else (args,)

    def __add__(self, other):
        return ZeroTensor(0, (self, other))

    def __sub__(self, other):
        return ZeroTensor(1, (self, other))

    def __mul__(self, other):
        return ZeroTensor(2, (self, other))

    def evaluate(self):
        if self.op is None:
            return self.args[0]
        args = [a.evaluate() if isinstance(a, ZeroTensor) else a for a in self.args]
        return evaluate_tensor_op(*args[:3]) if self.op < 3 else 0.0

def main():
    t = ZeroTensor(1.0) + ZeroTensor(2.0) * ZeroTensor(3.0)
    now = datetime.now().timestamp()
    jd = 2450000.0 + now / 86400.0
    traj = lorenz_tensor(100)
    mod_traj = astro_tensor_mul(traj, 45.0, 90.0, jd)
    result = t.evaluate() * mod_traj.mean()
    data = {"jd": jd, "result": result, "traj_mean": mod_traj.mean()}
    with open("build/zerotensor.json", "w") as f:
        json.dump(data, f)
    print(f"Evaluated: {result}")

if __name__ == "__main__":
    main()
