classdef CelestialZO < handle
    properties
        astroOffset;
        perturbations;
        primes;
        epsilon = 1e-6;
        quantumFactor = 1.0;
    end

    methods
        function obj = CelestialZO()
            obj.astroOffset = arrayfun(@CelestialZO.astroOffsetFn, 0:999);
            obj.perturbations = AstroParams.empty(0, 100);
            for i = 1:100
                obj.perturbations(i) = AstroParams();
            end
            obj.primes = arrayfun(@AstroParams.nextPrime, 2:1001);
        end

        function offset = astroOffsetFn(~, i)
            jd = getJulianDay();
            angle = jd * pi * 2.0 / 365.25;
            sinAngle = sin(angle);
            cosAngle = cos(angle);
            offset = sinAngle + cosAngle * i * 0.01;
        end

        function jd = getJulianDay()
            now = now();
            jd = now / 86400.0 + 2440587.5;
        end

        function result = computeOrbit(obj, params)
            jd = getJulianDay();
            n = length(params);
            result = zeros(1, 2 * n);
            for i = 1:n
                angle = jd * i * pi * 2.0 / 365.25;
                orbitX = sin(angle) * obj.astroOffset(mod(i-1, length(obj.astroOffset)) + 1);
                orbitY = cos(angle) * obj.astroOffset(mod(i-1, length(obj.astroOffset)) + 1);
                result(2*i-1) = params(i) * 1.0 + orbitX * 0.05;
                result(2*i) = orbitY * 0.05;
            end
        end

        function diff = finiteDiff(obj, params, f, dim)
            orig = params(dim);
            plusParams = params;
            plusParams(dim) = orig + obj.perturbations(1).epsilon * obj.perturbations(1).primes(1);
            fPlus = f(plusParams);
            minusParams = params;
            minusParams(dim) = orig - obj.perturbations(1).epsilon * obj.perturbations(1).primes(1);
            fMinus = f(minusParams);
            diff = (fPlus - fMinus) / (2.0 * obj.perturbations(1).epsilon * obj.perturbations(1).primes(1));
        end

        function grad = estimateGradient(obj, params, f)
            n = length(params);
            grad = zeros(1, n);
            numWorkers = 4; % fixed
            chunkSize = ceil(n / numWorkers);
            parfor tid = 1:numWorkers
                rng(tid); % seed per worker
                start = (tid-1) * chunkSize + 1;
                endIdx = min(start + chunkSize - 1, n);
                localGrad = zeros(1, n);
                for d = start:endIdx
                    diff = obj.finiteDiff(params, f, d);
                    noise = 0.9 + rand() * 0.2;
                    localGrad(d) = diff * obj.quantumFactor * noise;
                end
                grad = grad + localGrad;
            end
        end

        function updateParams(obj, params, f)
            orb = obj.computeOrbit(params);
            grad = obj.estimateGradient(params, f);
            n = length(params);
            numWorkers = 4;
            chunkSize = ceil(n / numWorkers);
            parfor tid = 1:numWorkers
                start = (tid-1) * chunkSize + 1;
                endIdx = min(start + chunkSize - 1, n);
                for i = start:endIdx
                    params(i) = params(i) - grad(i) * 1e-4 * obj.astroOffset(mod(i-1, length(obj.astroOffset)) + 1);
                end
            end
        end

        function trained = train(obj, iterations)
            params = ones(1, 5);
            for it = 1:iterations
                obj.updateParams(params, @(pars) objective(pars));
            end
            trained = params;
        end
    end
end

