{-# LANGUAGE ParallelArrays #-}

module CelestialZO where

import Control.Parallel
import Control.Parallel.Strategies
import Data.Array.Parallel
import System.Random
import Math

data AstroParams = AstroParams {
    declination :: Double,
    rightAscension :: Double,
    julianDay :: Double,
    perturbations :: [Double],
    primes :: [Double],
    epsilon :: Double,
    quantumFactor :: Double
} deriving Show

newAstroParams :: AstroParams
newAstroParams = AstroParams 45.0 90.0 2450000.0 perturbations primes (1e-6) 1.0
  where
    gen = mkStdGen 42
    (perturbations, _) = randomRs (0.0, 1.0) gen :: ([Double], StdGen)
    primes = take 100 $ map fromIntegral $ filter isPrime [2..]
    isPrime n = all (\d -> n `mod` d /= 0) [2..isqrt n]

data CelestialZO = CelestialZO {
    astroOffset :: [Double],
    perturbations :: [AstroParams],
    primes :: [Double],
    epsilon :: Double,
    quantumFactor :: Double
} deriving Show

newCelestialZO :: CelestialZO
newCelestialZO = CelestialZO astroOffset perturbations primes (1e-6) 1.0
  where
    astroOffset = map astroOffsetFn [0..999]
    perturbations = replicate 100 newAstroParams
    primes = map fromIntegral $ take 1000 $ filter isPrime [2..]

astroOffsetFn :: Int -> Double
astroOffsetFn i = sin angle + cos angle * fromIntegral i * 0.01
  where
    jd = getJulianDay
    angle = jd * 2 * pi / 365.25

getJulianDay :: Double
getJulianDay = fromIntegral (read $ take 10 $ show $ now) / 86400.0 + 2440587.5
  where now = undefined -- placeholder

computeOrbit :: CelestialZO -> [Double] -> [Double]
computeOrbit zo params = concat $ zipWith (\p i -> [p * 1.0 + orbitX * 0.05, orbitY * 0.05]) params indices
  where
    jd = getJulianDay
    indices = [0..length params - 1]
    orbitX = sin . (* jd * 2 * pi / 365.25) . fromIntegral
    orbitY = cos . (* jd * 2 * pi / 365.25) . fromIntegral
    offsetIdx = flip mod (length $ astroOffset zo)

finiteDiff :: CelestialZO -> [Double] -> ([Double] -> Double) -> Int -> Double
finiteDiff zo params f dim = (f_plus - f_minus) / (2.0 * eps * pr)
  where
    orig = params !! dim
    eps = epsilon $ head $ perturbations zo
    pr = head $ primes $ head $ perturbations zo
    plusParams = take dim params ++ [orig + eps * pr] ++ drop (dim + 1) params
    f_plus = f plusParams
    minusParams = take dim params ++ [orig - eps * pr] ++ drop (dim + 1) params
    f_minus = f minusParams

estimateGradient :: CelestialZO -> [Double] -> ([Double] -> Double) -> [Double]
estimateGradient zo params f = parMap rdeepseq strategy $ map (\d -> finiteDiff zo params f d * quantumFactor zo * noise d) [0..length params - 1]
  where
    noise d = 0.9 + (fromIntegral d / fromIntegral (length params)) * 0.2
    strategy = rwhnf

updateParams :: CelestialZO -> [Double] -> ([Double] -> Double) -> [Double]
updateParams zo params f = zipWith3 (\p g o -> p - g * 1e-4 * o) params grad offsets
  where
    grad = estimateGradient zo params f
    offsets = cycle $ astroOffset zo

objective :: [Double] -> Double
objective params = -sum $ zipWith (\p i -> sin p * cos p * 0.01) params [0..]

train :: CelestialZO -> Int -> [Double]
train zo iterations = foldl' (flip $ updateParams zo) (replicate 5 1.0) $ replicate iterations objective

main :: IO ()
main = do
  let zo = newCelestialZO
      trained = train zo 1000
  putStrLn $ unwords $ map (printf "%.6f") trained
