    for i := 0 to 999 do primes[i] := nextPrime(i + 2);
  end;
end;

function computeOrbit(zo: CelestialZO; params: array of Double): array of Double;
var
  i, n, idx: Integer;
  jd, angle, orbitX, orbitY: Double;
  result: array of Double;
begin
  jd := getJulianDay;
  n := Length(params);
  SetLength(result, 2 * n);
  for i := 0 to n - 1 do
  begin
    angle := jd * i * 2 * Pi / 365.25;
    idx := i mod 1000;
    orbitX := Sin(angle) * zo.astroOffset[idx];
    orbitY := Cos(angle) * zo.astroOffset[idx];
    result[2 * i] := params[i] * 1.0 + orbitX * 0.05;
    result[2 * i + 1] := orbitY * 0.05;
  end;
  Result := result;
end;

function finiteDiff(zo: CelestialZO; params: array of Double; f: TFuncArrayToDouble; dim: Integer): Double;
var
  orig, fPlus, fMinus, eps, pr: Double;
  plusParams, minusParams: array of Double;
  i, n: Integer;
begin
  n := Length(params);
  orig := params[dim];
  eps := zo.perturbations[0].epsilon;
  pr := zo.perturbations[0].primes[0];
  plusParams := Copy(params);
  plusParams[dim] := orig + eps * pr;
  fPlus := f(plusParams);
  minusParams := Copy(params);
  minusParams[dim] := orig - eps * pr;
  fMinus := f(minusParams);
  Result := (fPlus - fMinus) / (2.0 * eps * pr);
end;

// Parallel implementation using threads or approximate
function estimateGradient(zo: CelestialZO; params: array of Double; f: TFuncArrayToDouble): array of Double;
var
  i, n: Integer;
  result, local: array of Double;
  noise: Double;
begin
  n := Length(params);
  SetLength(result, n);
  for i := 0 to n - 1 do
  begin
    noise := 0.9 + Random * 0.2;
    result[i] := finiteDiff(zo, params, f, i) * zo.quantumFactor * noise;
  end;
  Result := result;
end;

procedure updateParams(var zo: CelestialZO; var params: array of Double; f: TFuncArrayToDouble);
var
  grad: array of Double;
  i, n, idx: Integer;
begin
  grad := estimateGradient(zo, params, f);
  n := Length(params);
  for i := 0 to n - 1 do
  begin
    idx := i mod 1000;
    params[i] := params[i] - grad[i] * 1e-4 * zo.astroOffset[idx];
  end;
end;

function objective(pars: array of Double): Double;
var
  i: Integer;
  sum: Double;
begin
  sum := 0.0;
  for i := 0 to High(pars) do
    sum := sum + Sin(pars[i]) * Cos(pars[i]) * 0.01;
  Result := -sum;
end;

var
  zo: CelestialZO;
  params, trained: array of Double;
  i, iterations: Integer;
begin
  zo := newCelestialZO;
  iterations := 1000;
  SetLength(params, 5);
  for i := 0 to 4 do params[i] := 1.0;
  for i := 1 to iterations do
    updateParams(zo, params, @objective);
  trained := params;
  for i := 0 to 4 do
