(define-module (celestial-zo)
  #:use-module (srfi srfi-1)
  #:use-module (ice-9 threads)
  #:use-module (ice-9 random))

(define-record-type <astro-params>
  (make-astro-params declination right-ascension julian-day perturbations primes epsilon quantum-factor)
  astro-params?
  (declination astro-params-declination)
  (right-ascension astro-params-right-ascension)
  (julian-day astro-params-julian-day)
  (perturbations astro-params-perturbations)
  (primes astro-params-primes)
  (epsilon astro-params-epsilon)
  (quantum-factor astro-params-quantum-factor))

(define (new-astro-params)
  (let* ((rng (random-state-from-platform))
         (perturbations (iota 100 0 (lambda (i) (uniform 0 1 rng))))
         (primes (iota 100 2 (lambda (i) (next-prime (+ i 1))))))
    (make-astro-params 45.0 90.0 2450000.0 perturbations primes 1e-6 1.0)))

(define (next-prime n)
  (let loop ((p n))
    (if (prime? p) p (loop (+ p 1)))))

(define-record-type <celestial-zo>
  (make-celestial-zo astro-offset perturbations primes epsilon quantum-factor)
  celestial-zo?
  (astro-offset celestial-zo-astro-offset)
  (perturbations celestial-zo-perturbations)
  (primes celestial-zo-primes)
  (epsilon celestial-zo-epsilon)
  (quantum-factor celestial-zo-quantum-factor))

(define (new-celestial-zo)
  (let* ((astro-offset (iota 1000 0 (lambda (i) (astro-offset-fn i))))
         (perturbations (iota 100 0 (lambda (_) (new-astro-params))))
         (primes (iota 1000 2 (lambda (i) (next-prime (+ i 1))))))
    (make-celestial-zo astro-offset perturbations primes 1e-6 1.0)))

(define (astro-offset-fn i)
  (let ((jd (get-julian-day)))
    (let ((angle (* jd 2 pi / 365.25)))
      (+ (sin angle) (* (cos angle) i 0.01)))))

(define (get-julian-day)
  (let ((now (current-time)))
    (+ (/ (time-second now) 86400.0) 2440587.5)))

(define (compute-orbit zo params)
  (let ((jd (get-julian-day)))
    (apply append
           (map (lambda (p i)
                  (let ((angle (* jd i 2 pi / 365.25)))
                    (let ((idx (modulo i (length (celestial-zo-astro-offset zo)))))
                      (let ((off (list-ref (celestial-zo-astro-offset zo) idx)))
                        (list (+ (* p 1.0) (* (sin angle) off 0.05))
                              (* (cos angle) off 0.05)))))))
                params (iota (length params))))))

(define (finite-diff zo params f dim)
  (let ((orig (list-ref params dim))
        (pert (car (celestial-zo-perturbations zo)))
        (eps (astro-params-epsilon pert))
        (pr (car (astro-params-primes pert))))
    (let ((plus-params (list-set params dim (+ orig (* eps pr))))
          (f-plus (f plus-params)))
      (let ((minus-params (list-set params dim (- orig (* eps pr))))
            (f-minus (f minus-params)))
        (/ (- f-plus f-minus) (* 2.0 eps pr))))))

(define (estimate-gradient zo params f)
  (let ((n (length params)))
    (par-map (lambda (d)
               (let ((diff (finite-diff zo params f d))
                     (noise (+ 0.9 (* (uniform 0 1) 0.2))))
                 (* diff (celestial-zo-quantum-factor zo) noise)))
             (iota n))))

(define (update-params zo params f)
  (let ((grad (estimate-gradient zo params f)))
    (map (lambda (p g i)
           (let ((idx (modulo i (length (celestial-zo-astro-offset zo)))))
             (- p (* g 1e-4 (list-ref (celestial-zo-astro-offset zo) idx)))))
         params grad (iota (length params)))))

(define (objective params)
  (let ((sum 0.0))
    (fold (lambda (p sum)
            (+ sum (* (sin p) (cos p) 0.01))) 0.0 params)
    (- sum)))

(define (train zo iterations)
  (let loop ((it iterations) (params (make-list 5 1.0)))
    (if (zero? it)
        params
        (loop (- it 1) (update-params zo params objective)))))

(define (main)
  (let ((zo (new-celestial-zo))
        (trained (train zo 1000)))
    (format #t "~{~6,2F ~}~%" (map (lambda (p) p) trained))))

(main)
