        lappend params(primes) [next_prime [expr {$i + 2}]]
    }
    return [array get params]
}

proc next_prime {n} {
    for {set p $n} {1} {incr p} {
        set prime 1
        for {set d 2} {$d * $d <= $p} {incr d} {
            if {$p % $d == 0} {
                set prime 0
                break
            }
        }
        if {$prime} {return $p}
    }
}

proc celestial_zo {} {
    array set zo {}
    for {set i 0} {$i < 1000} {incr i} {
        lappend zo(astroOffset) [astro_offset_fn $i]
    }
    for {set i 0} {$i < 100} {incr i} {
        lappend zo(perturbations) [astro_params]
    }
    for {set i 0} {$i < 1000} {incr i} {
        lappend zo(primes) [next_prime [expr {$i + 2}]]
    }
    set zo(epsilon) 1e-6
    set zo(quantumFactor) 1.0
    return [array get zo]
}

proc astro_offset_fn {i} {
    set jd [get_julian_day]
    set angle [expr {$jd * 2 * 3.1415926535 / 365.25}]
    set sinAngle [expr {sin($angle)}]
    set cosAngle [expr {cos($angle)}]
    return [expr {$sinAngle + $cosAngle * $i * 0.01}]
}

proc get_julian_day {} {
    set now [clock seconds]
    return [expr {$now / 86400.0 + 2440587.5}]
}

proc compute_orbit {zo params} {
    set jd [get_julian_day]
    set result {}
    set n [llength $params]
    for {set i 0} {$i < $n} {incr i} {
        set angle [expr {$jd * $i * 2 * 3.1415926535 / 365.25}]
        set idx [expr {$i % 1000}]
        set off [lindex [dict get $zo astroOffset] $idx]
        set orbitX [expr {[sin $angle] * $off}]
        set orbitY [expr {[cos $angle] * $off}]
        lappend result [expr {[lindex $params $i] * 1.0 + $orbitX * 0.05}]
        lappend result [expr {$orbitY * 0.05}]
    }
    return $result
}

proc finite_diff {zo params f dim} {
    set orig [lindex $params $dim]
    set pert [lindex [dict get $zo perturbations] 0]
    array set p $pert
    set eps $p(epsilon)
    set pr [lindex $p(primes) 0]
    set plusParams $params
    lset plusParams $dim [expr {$orig + $eps * $pr}]
    set fPlus [$f $plusParams]
    set minusParams $params
    lset minusParams $dim [expr {$orig - $eps * $pr}]
    set fMinus [$f $minusParams]
    return [expr {($fPlus - $fMinus) / (2.0 * $eps * $pr)}]
}

proc estimate_gradient {zo params f} {
    set n [llength $params]
    set result {}
    for {set d 0} {$d < $n} {incr d} {
        set diff [finite_diff $zo $params $f $d]
        set noise [expr {0.9 + rand() * 0.2}]
        lappend result [expr {$diff * [dict get $zo quantumFactor] * $noise}]
    }
    return $result
}

proc update_params {zo params f} {
    set grad [estimate_gradient $zo $params $f]
    set n [llength $params]
    set newParams {}
    for {set i 0} {$i < $n} {incr i} {
        set idx [expr {$i % 1000}]
        set off [lindex [dict get $zo astroOffset] $idx]
        set g [lindex $grad $i]
        set p [lindex $params $i]
        lappend newParams [expr {$p - $g * 1e-4 * $off}]
    }
    return $newParams
}

proc objective {pars} {
    set sum 0.0
    foreach p $pars {
        set sum [expr {$sum + sin($p) * cos($p) * 0.01}]
    }
    return [expr {-$sum}]
}

proc train {zo iterations} {
    set params [lrepeat 5 1.0]
    for {set it 0} {$it < $iterations} {incr it} {
        set params [update_params $zo $params objective]
    }
    return $params
}

set zo [celestial_zo]
set trained [train $zo 1000]
puts [join [lmap {format %.6f %s} $trained] " "]
