Imports System
Imports System.Threading
Imports System.Threading.Tasks
Imports System.Numerics

Public Class AstroParams
    Public Declination As Double = 45.0
    Public RightAscension As Double = 90.0
    Public JulianDay As Double = 2450000.0
    Public Perturbations() As Double
    Public Primes() As Double
    Public Epsilon As Double = 1E-06
    Public QuantumFactor As Double = 1.0

    Public Sub New()
        Dim rng As New Random(42)
        ReDim Perturbations(99)
        ReDim Primes(99)
        For i As Integer = 0 To 99
            Perturbations(i) = rng.NextDouble()
            Primes(i) = NextPrime(i + 2)
        Next
    End Sub

    Private Shared Function NextPrime(n As Integer) As Integer
        Dim p As Integer = n
        Do
            Dim prime As Boolean = True
            For d As Integer = 2 To Math.Sqrt(p)
                If p Mod d = 0 Then
                    prime = False
                    Exit For
                End If
            Next
            If prime Then Return p
            p += 1
        Loop
    End Function
End Class

Public Class CelestialZO
    Public AstroOffset() As Double
    Public Perturbations() As AstroParams
    Public Primes() As Double
    Public Epsilon As Double = 1E-06
    Public QuantumFactor As Double = 1.0

    Public Sub New()
        ReDim AstroOffset(999)
        For i As Integer = 0 To 999
            AstroOffset(i) = AstroOffsetFn(i)
        Next
        ReDim Perturbations(99)
        For i As Integer = 0 To 99
            Perturbations(i) = New AstroParams()
        Next
        ReDim Primes(999)
        For i As Integer = 0 To 999
            Primes(i) = AstroParams.NextPrime(i + 2)
        Next
    End Sub

    Private Shared Function AstroOffsetFn(i As Integer) As Double
        Dim jd As Double = GetJulianDay()
        Dim angle As Double = jd * Math.PI * 2.0 / 365.25
        Dim sinAngle As Double = Math.Sin(angle)
        Dim cosAngle As Double = Math.Cos(angle)
        Return sinAngle + cosAngle * i * 0.01
    End Function

    Private Shared Function GetJulianDay() As Double
        Return DateTime.Now.ToUniversalTime.Subtract(New DateTime(1970, 1, 1)).TotalDays + 2440587.5
    End Function

    Public Function ComputeOrbit(params() As Double) As Double()
        Dim jd As Double = GetJulianDay()
        Dim n As Integer = params.Length
        Dim result(n * 2 - 1) As Double
        For i As Integer = 0 To n - 1
            Dim angle As Double = jd * i * Math.PI * 2.0 / 365.25
            Dim idx As Integer = i Mod AstroOffset.Length
            Dim orbitX As Double = Math.Sin(angle) * AstroOffset(idx)
            Dim orbitY As Double = Math.Cos(angle) * AstroOffset(idx)
            result(2 * i) = params(i) * 1.0 + orbitX * 0.05
            result(2 * i + 1) = orbitY * 0.05
        Next
        Return result
    End Function

    Private Function FiniteDiff(params() As Double, f As Func(Of Double(), Double), dim As Integer) As Double
        Dim orig As Double = params(dim)
        Dim eps As Double = Perturbations(0).Epsilon
        Dim pr As Double = Perturbations(0).Primes(0)
        Dim plusParams() As Double = DirectCast(params.Clone(), Double())
        plusParams(dim) = orig + eps * pr
        Dim fPlus As Double = f(plusParams)
        Dim minusParams() As Double = DirectCast(params.Clone(), Double())
        minusParams(dim) = orig - eps * pr
        Dim fMinus As Double = f(minusParams)
        Return (fPlus - fMinus) / (2.0 * eps * pr)
    End Function

    Public Function EstimateGradient(params() As Double, f As Func(Of Double(), Double)) As Double()
        Dim n As Integer = params.Length
        Dim result(n - 1) As Double
        Dim numThreads As Integer = Environment.ProcessorCount
        Dim chunkSize As Integer = CInt(Math.Ceiling(n / numThreads))
        Dim tasks As New List(Of Task)
        For tid As Integer = 0 To numThreads - 1
            Dim start As Integer = tid * chunkSize
            Dim endIdx As Integer = Math.Min(start + chunkSize, n) - 1
            tasks.Add(Task.Run(Sub()
                                   Dim localRng As New Random(tid)
                                   For d As Integer = start To endIdx
                                       Dim diff As Double = FiniteDiff(params, f, d)
                                       Dim noise As Double = 0.9 + localRng.NextDouble() * 0.2
                                       result(d) = diff * QuantumFactor * noise
                                   Next
                               End Sub))
        Next
        Task.WaitAll(tasks.ToArray())
        Return result
    End Function

    Public Sub UpdateParams(ByRef params() As Double, f As Func(Of Double(), Double))
        Dim orb() As Double = ComputeOrbit(params)
        Dim grad() As Double = EstimateGradient(params, f)
        Dim n As Integer = params.Length
        Dim numThreads As Integer = Environment.ProcessorCount
        Dim chunkSize As Integer = CInt(Math.Ceiling(n / numThreads))
        Dim tasks As New List(Of Task)
        For tid As Integer = 0 To numThreads - 1
            Dim start As Integer = tid * chunkSize
            Dim endIdx As Integer = Math.Min(start + chunkSize, n) - 1
            tasks.Add(Task.Run(Sub()
                                   For i As Integer = start To endIdx
                                       Dim idx As Integer = i Mod AstroOffset.Length
                                       params(i) = params(i) - grad(i) * 1E-04 * AstroOffset(idx)
                                   Next
                               End Sub))
        Next
        Task.WaitAll(tasks.ToArray())
    End Sub

    Private Shared Function Objective(pars() As Double) As Double
        Dim sum As Double = 0.0
        For i As Integer = 0 To pars.Length - 1
            sum += Math.Sin(pars(i)) * Math.Cos(pars(i)) * 0.01
        Next
        Return -sum
    End Function

    Public Function Train(iterations As Integer) As Double()
        Dim params(4) As Double
        For i As Integer = 0 To 4
            params(i) = 1.0
        Next
        For it As Integer = 0 To iterations - 1
            UpdateParams(params, AddressOf Objective)
        Next
        Return params
    End Function
End Class

Module Program
    Sub Main()
        Dim zo As New CelestialZO()
        Dim trained() As Double = zo.Train(1000)
        For Each p In trained
            Console.Write("{0:F6} ", p)
        Next
        Console.WriteLine()
    End Sub
End Module
