using System;
using System.Linq;
using System.Numerics;
using System.Threading.Tasks;

public class AstroParams
{
    public double Declination { get; set; } = 45.0;
    public double RightAscension { get; set; } = 90.0;
    public double JulianDay { get; set; } = 2450000.0;
    public double[] Perturbations { get; set; }
    public double[] Primes { get; set; }
    public double Epsilon { get; set; } = 1e-6;
    public double QuantumFactor { get; set; } = 1.0;

    public AstroParams()
    {
        var rng = new Random(42);
        Perturbations = Enumerable.Range(0, 100).Select(_ => rng.NextDouble()).ToArray();
        Primes = Enumerable.Range(0, 100).Select(i => NextPrime(i + 2)).ToArray();
    }

    private static double NextPrime(int n)
    {
        for (int p = n;; p++)
        {
            bool prime = true;
            for (int d = 2; d * d <= p; d++) if (p % d == 0) { prime = false; break; }
            if (prime) return p;
        }
    }
}

public class CelestialZO
{
    public double[] AstroOffset { get; set; }
    public AstroParams[] Perturbations { get; set; }
    public double[] Primes { get; set; }
    public double Epsilon { get; set; } = 1e-6;
    public double QuantumFactor { get; set; } = 1.0;

    public CelestialZO()
    {
        AstroOffset = Enumerable.Range(0, 1000).Select(AstroOffsetFn).ToArray();
        Perturbations = Enumerable.Range(0, 100).Select(_ => new AstroParams()).ToArray();
        Primes = Enumerable.Range(0, 1000).Select(i => AstroParams.NextPrime(i + 2)).ToArray();
    }

    private static double AstroOffsetFn(int i)
    {
        double jd = GetJulianDay();
        double angle = jd * Math.PI * 2.0 / 365.25;
        double sinAngle = Math.Sin(angle);
        double cosAngle = Math.Cos(angle);
        return sinAngle + cosAngle * i * 0.01;
    }

    private static double GetJulianDay() => DateTimeOffset.UtcNow.ToUnixTimeSeconds() / 86400.0 + 2440587.5;

    public double[] ComputeOrbit(double[] parameters)
    {
        double jd = GetJulianDay();
        int n = parameters.Length;
        var result = new double[2 * n];
        for (int i = 0; i < n; i++)
        {
            double angle = jd * i * Math.PI * 2.0 / 365.25;
            int idx = i % AstroOffset.Length;
            double orbitX = Math.Sin(angle) * AstroOffset[idx];
            double orbitY = Math.Cos(angle) * AstroOffset[idx];
            result[2 * i] = parameters[i] * 1.0 + orbitX * 0.05;
            result[2 * i + 1] = orbitY * 0.05;
        }
        return result;
    }

    private double FiniteDiff(double[] parameters, Func<double[], double> f, int dim)
    {
        double orig = parameters[dim];
        double eps = Perturbations[0].Epsilon;
        double pr = Perturbations[0].Primes[0];
        var plusParams = (double[])parameters.Clone();
        plusParams[dim] = orig + eps * pr;
        double fPlus = f(plusParams);
        var minusParams = (double[])parameters.Clone();
        minusParams[dim] = orig - eps * pr;
        double fMinus = f(minusParams);
        return (fPlus - fMinus) / (2.0 * eps * pr);
    }

    public double[] EstimateGradient(double[] parameters, Func<double[], double> f)
    {
        int n = parameters.Length;
        var result = new double[n];
        var numThreads = Environment.ProcessorCount;
        var chunkSize = (int)Math.Ceiling((double)n / numThreads);
        Parallel.For(0, numThreads, tid =>
        {
            var rng = new Random(tid);
            int start = tid * chunkSize;
            int endIdx = Math.Min(start + chunkSize, n);
            for (int d = start; d < endIdx; d++)
            {
                double diff = FiniteDiff(parameters, f, d);
                double noise = 0.9 + rng.NextDouble() * 0.2;
                result[d] = diff * QuantumFactor * noise;
            }
        });
        return result;
    }

    public void UpdateParams(ref double[] parameters, Func<double[], double> f)
    {
        var orb = ComputeOrbit(parameters);
        var grad = EstimateGradient(parameters, f);
        int n = parameters.Length;
        var numThreads = Environment.ProcessorCount;
        var chunkSize = (int)Math.Ceiling((double)n / numThreads);
        Parallel.For(0, numThreads, tid =>
        {
            int start = tid * chunkSize;
            int endIdx = Math.Min(start + chunkSize, n);
            for (int i = start; i < endIdx; i++)
            {
                int idx = i % AstroOffset.Length;
                parameters[i] -= grad[i] * 1e-4 * AstroOffset[idx];
            }
        });
    }

    private static double Objective(double[] pars)
    {
        double sum = 0.0;
        for (int i = 0; i < pars.Length; i++) sum += Math.Sin(pars[i]) * Math.Cos(pars[i]) * 0.01;
        return -sum;
    }

    public double[] Train(int iterations)
    {
        var parameters = new double[5];
        for (int i = 0; i < 5; i++) parameters[i] = 1.0;
        for (int it = 0; it < iterations; it++)
            UpdateParams(ref parameters, Objective);
        return parameters;
    }
}

class Program
{
    static void Main()
    {
        var zo = new CelestialZO();
        var trained = zo.Train(1000);
        Console.WriteLine(string.Join(" ", trained.Select(p => $"{p:F6}")));
    }
}
