open System
open System.Threading.Tasks
open System.Numerics

type AstroParams() =
    member val Declination = 45.0 with get, set
    member val RightAscension = 90.0 with get, set
    member val JulianDay = 2450000.0 with get, set
    member val Perturbations = Array.zeroCreate<double> 100 with get, set
    member val Primes = Array.zeroCreate<double> 100 with get, set
    member val Epsilon = 1e-6 with get, set
    member val QuantumFactor = 1.0 with get, set

    do
        let rng = System.Random(42)
        for i in 0..99 do
            this.Perturbations.[i] <- rng.NextDouble()
            this.Primes.[i] <- NextPrime(i + 2)

    static member private NextPrime(n: int) : double =
        let rec findPrime p =
            let isPrime = seq {2..int (sqrt (double p))} |> Seq.forall (fun d -> p % d <> 0)
            if isPrime then p else findPrime (p + 1)
        double (findPrime n)

type CelestialZO() =
    member val AstroOffset = Array.zeroCreate<double> 1000 with get, set
    member val Perturbations = Array.zeroCreate<AstroParams> 100 with get, set
    member val Primes = Array.zeroCreate<double> 1000 with get, set
    member val Epsilon = 1e-6 with get, set
    member val QuantumFactor = 1.0 with get, set

    do
        for i in 0..999 do
            this.AstroOffset.[i] <- AstroOffsetFn i
        for i in 0..99 do
            this.Perturbations.[i] <- AstroParams()
        for i in 0..999 do
            this.Primes.[i] <- AstroParams.NextPrime(i + 2)

    static member private AstroOffsetFn(i: int) : double =
        let jd = CelestialZO.GetJulianDay()
        let angle = jd * Math.PI * 2.0 / 365.25
        let sinAngle = sin angle
        let cosAngle = cos angle
        sinAngle + cosAngle * double i * 0.01

    static member private GetJulianDay() : double = DateTimeOffset.UtcNow.ToUnixTimeSeconds() / 86400.0 + 2440587.5

    member this.ComputeOrbit(parameters: double[]) : double[] =
        let jd = CelestialZO.GetJulianDay()
        let n = parameters.Length
        let result = Array.zeroCreate<double> (2 * n)
        for i in 0..n-1 do
            let angle = jd * double i * Math.PI * 2.0 / 365.25
            let idx = i % this.AstroOffset.Length
            let orbitX = sin angle * this.AstroOffset.[idx]
            let orbitY = cos angle * this.AstroOffset.[idx]
            result.[2*i] <- parameters.[i] * 1.0 + orbitX * 0.05
            result.[2*i + 1] <- orbitY * 0.05
        result

    member private this.FiniteDiff(parameters: double[], f: Func<double[], double>, dim: int) : double =
        let orig = parameters.[dim]
        let eps = this.Perturbations.[0].Epsilon
        let pr = this.Perturbations.[0].Primes.[0]
        let plusParams = Array.copy parameters
        plusParams.[dim] <- orig + eps * pr
        let fPlus = f.Invoke(plusParams)
        let minusParams = Array.copy parameters
        minusParams.[dim] <- orig - eps * pr
        let fMinus = f.Invoke(minusParams)
        (fPlus - fMinus) / (2.0 * eps * pr)

    member this.EstimateGradient(parameters: double[], f: Func<double[], double>) : double[] =
        let n = parameters.Length
        let result = Array.zeroCreate<double> n
        let numThreads = Environment.ProcessorCount
        let chunkSize = int (Math.Ceiling(double n / double numThreads))
        Parallel.For(0, numThreads, fun tid ->
            let rng = new System.Random(tid)
            let start = tid * chunkSize
            let endIdx = Math.Min(start + chunkSize, n)
            for d in start .. endIdx - 1 do
                let diff = this.FiniteDiff(parameters, f, d)
                let noise = 0.9 + rng.NextDouble() * 0.2
                result.[d] <- diff * this.QuantumFactor * noise
        ) |> ignore
        result

    member this.UpdateParams(parameters: byref<double[]>, f: Func<double[], double>) =
        let orb = this.ComputeOrbit(parameters)
        let grad = this.EstimateGradient(parameters, f)
        let n = parameters.Length
        let numThreads = Environment.ProcessorCount
        let chunkSize = int (Math.Ceiling(double n / double numThreads))
        Parallel.For(0, numThreads, fun tid ->
            let start = tid * chunkSize
            let endIdx = Math.Min(start + chunkSize, n)
            for i in start .. endIdx - 1 do
                let idx = i % this.AstroOffset.Length
                parameters.[i] <- parameters.[i] - grad.[i] * 1e-4 * this.AstroOffset.[idx]
        ) |> ignore

    static member private Objective(pars: double[]) : double =
        let sum = pars |> Array.sumBy (fun p -> Math.Sin(p) * Math.Cos(p) * 0.01)
        -sum

    member this.Train(iterations: int) : double[] =
        let parameters = Array.create 5 1.0
        for it in 0 .. iterations - 1 do
            this.UpdateParams(&parameters, Func<double[], double>(Objective))
        parameters

[<EntryPoint>]
let main _ =
    let zo = new CelestialZO()
    let trained = zo.Train(1000)
    trained |> Array.iter (fun p -> printf "%.6f " p)
    printfn ""
    0
